node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables);
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log(t.name + ' columns:', cols.map(c => c.name));
  // Check for alice
  for (const c of cols) {
    try {
      const rows = db.prepare('SELECT * FROM ' + t.name + ' WHERE ' + c.name + ' LIKE ?').all('%alice%');
      if (rows.length > 0) {
        console.log('Found alice in ' + t.name + '.' + c.name + ':', rows);
      }
    } catch(e) {}
  }
}
"

